    "Στα πορτογαλικά ο προσδιοριστής και το ουσιαστικό του έχουν το ίδιο γένος και αριθμό (a casa, os problemas, a nossa equipe), όπως και το επίθετο κατηγορίας που τα ακολουθεί (a política econômica).",
