    "Polska citattecken öppnar nere och stänger uppe: „cytat”, med »…« för ett citat i ett citat.",
    "Polnische Anführungszeichen öffnen unten und schließen oben: „cytat”, mit »…« für ein Zitat im Zitat.",
    "Cudzysłów otwieramy na dole, a zamykamy u góry: „cytat”; cudzysłów wewnątrz cytatu to »…«.",
    "As aspas polonesas abrem embaixo e fecham em cima: „cytat”, com »…« para uma citação dentro de outra.",
