  review_msg_pl_extra_comma: [
    "No comma here in Polish: not after a linking word (“Jednak miałem rację”), not right after “który”, and not before a single “ani”, “lub” or “oraz” between two words.",
    "Pas de virgule ici en polonais : ni après un mot de liaison (« Jednak miałem rację »), ni juste après « który », ni avant un seul « ani », « lub » ou « oraz » entre deux mots.",
    "Ovdje u poljskom nema zareza: ni iza veznog priloga („Jednak miałem rację”), ni odmah iza „który”, ni ispred jednog „ani”, „lub” ili „oraz” između dviju riječi.",
    "Aquí el polaco no lleva coma: ni tras un conector («Jednak miałem rację»), ni justo tras «który», ni antes de un solo «ani», «lub» u «oraz» entre dos palabras.",
    "Εδώ τα πολωνικά δεν βάζουν κόμμα: ούτε μετά από συνδετική λέξη («Jednak miałem rację»), ούτε αμέσως μετά το «który», ούτε πριν από ένα μόνο «ani», «lub» ή «oraz» ανάμεσα σε δύο λέξεις.",
    "Inget kommatecken här på polska: inte efter ett sambandsord (”Jednak miałem rację”), inte direkt efter ”który” och inte före ett ensamt ”ani”, ”lub” eller ”oraz” mellan två ord.",
    "Hier steht im Polnischen kein Komma: nicht nach einem Bindewort („Jednak miałem rację“), nicht direkt nach „który“ und nicht vor einem einzelnen „ani“, „lub“ oder „oraz“ zwischen zwei Wörtern.",
    "Tu nie stawiamy przecinka: po wyrazie łączącym („Jednak miałem rację”), tuż po „który” ani przed pojedynczym „ani”, „lub” czy „oraz” między dwoma wyrazami.",
    "Aqui o polonês não usa vírgula: nem depois de um conector (“Jednak miałem rację”), nem logo após “który”, nem antes de um único “ani”, “lub” ou “oraz” entre duas palavras.",
  ],
  review_msg_pl_comma_aside: [
    "Polish sets off an aside with a comma (“Co więcej, …”, “Krótko mówiąc, …”) and puts one before a repeated conjunction (“ani prośby, ani groźby”).",
    "Le polonais isole une incise par une virgule (« Co więcej, … », « Krótko mówiąc, … ») et en met une avant une conjonction répétée (« ani prośby, ani groźby »).",
    "Poljski odvaja umetak zarezom („Co więcej, …”, „Krótko mówiąc, …”) i stavlja ga ispred ponovljenog veznika („ani prośby, ani groźby”).",
    "El polaco aísla un inciso con coma («Co więcej, …», «Krótko mówiąc, …») y la pone antes de una conjunción repetida («ani prośby, ani groźby»).",
    "Τα πολωνικά χωρίζουν μια παρενθετική φράση με κόμμα («Co więcej, …», «Krótko mówiąc, …») και βάζουν κόμμα πριν από επαναλαμβανόμενο σύνδεσμο («ani prośby, ani groźby»).",
    "Polskan avgränsar ett inskott med kommatecken (”Co więcej, …”, ”Krótko mówiąc, …”) och sätter ett före en upprepad konjunktion (”ani prośby, ani groźby”).",
    "Im Polnischen wird ein Einschub mit Komma abgetrennt („Co więcej, …“, „Krótko mówiąc, …“), ebenso vor einer wiederholten Konjunktion („ani prośby, ani groźby“).",
    "Wtrącenie oddzielamy przecinkiem („Co więcej, …”, „Krótko mówiąc, …”), a przecinek stawiamy też przed powtórzonym spójnikiem („ani prośby, ani groźby”).",
    "O polonês separa um aparte com vírgula (“Co więcej, …”, “Krótko mówiąc, …”) e põe uma antes de uma conjunção repetida (“ani prośby, ani groźby”).",
  ],
  review_msg_pl_capitals: [
    "Polish writes weekdays, months and language or regional adjectives with a small letter (“w piątek”, “po angielsku”, “województwo mazowieckie”), and capitalizes every word of a holiday or a sea (“Wielki Piątek”, “Morze Bałtyckie”).",
    "Le polonais écrit les jours, les mois et les adjectifs de langue ou de région en minuscules (« w piątek », « po angielsku », « województwo mazowieckie ») et met une majuscule à chaque mot d’une fête ou d’une mer (« Wielki Piątek », « Morze Bałtyckie »).",
    "Poljski piše dane, mjesece i pridjeve jezika ili regije malim slovom („w piątek”, „po angielsku”, „województwo mazowieckie”), a svaku riječ blagdana ili mora velikim („Wielki Piątek”, „Morze Bałtyckie”).",
    "El polaco escribe los días, los meses y los adjetivos de lengua o región en minúscula («w piątek», «po angielsku», «województwo mazowieckie») y pone mayúscula a cada palabra de una festividad o un mar («Wielki Piątek», «Morze Bałtyckie»).",
    "Τα πολωνικά γράφουν τις ημέρες, τους μήνες και τα επίθετα γλώσσας ή περιοχής με μικρό («w piątek», «po angielsku», «województwo mazowieckie») και κάθε λέξη γιορτής ή θάλασσας με κεφαλαίο («Wielki Piątek», «Morze Bałtyckie»).",
    "Polskan skriver veckodagar, månader och språk- eller regionadjektiv med liten bokstav (”w piątek”, ”po angielsku”, ”województwo mazowieckie”) och varje ord i en högtid eller ett hav med stor (”Wielki Piątek”, ”Morze Bałtyckie”).",
    "Im Polnischen werden Wochentage, Monate und Sprach- oder Regionsadjektive kleingeschrieben („w piątek“, „po angielsku“, „województwo mazowieckie“), Feiertage und Meere in jedem Wort groß („Wielki Piątek“, „Morze Bałtyckie“).",
    "Dni tygodnia, miesiące oraz przymiotniki od nazw języków i regionów piszemy małą literą („w piątek”, „po angielsku”, „województwo mazowieckie”), a nazwy świąt i mórz – każdy wyraz wielką („Wielki Piątek”, „Morze Bałtyckie”).",
    "O polonês escreve dias da semana, meses e adjetivos de língua ou região com minúscula (“w piątek”, “po angielsku”, “województwo mazowieckie”) e cada palavra de um feriado ou mar com maiúscula (“Wielki Piątek”, “Morze Bałtyckie”).",
  ],
  review_msg_pl_conjunction_ending: [
    "After “żeby”, “aby” or “gdyby” the person ending joins the conjunction and the verb stays in the bare past form: “żebym zrobił”, “gdybyś przyszła”.",
    "Après « żeby », « aby » ou « gdyby », la désinence de personne se colle à la conjonction et le verbe reste au passé simple : « żebym zrobił », « gdybyś przyszła ».",
    "Iza „żeby”, „aby” ili „gdyby” lični nastavak ide na veznik, a glagol ostaje u golom obliku prošlog vremena: „żebym zrobił”, „gdybyś przyszła”.",
    "Tras «żeby», «aby» o «gdyby» la terminación de persona va en la conjunción y el verbo queda en la forma simple de pasado: «żebym zrobił», «gdybyś przyszła».",
    "Μετά το «żeby», «aby» ή «gdyby» η προσωπική κατάληξη πηγαίνει στον σύνδεσμο και το ρήμα μένει σε γυμνό τύπο αορίστου: «żebym zrobił», «gdybyś przyszła».",
    "Efter ”żeby”, ”aby” eller ”gdyby” sätts personändelsen på konjunktionen och verbet står i bar preteritumform: ”żebym zrobił”, ”gdybyś przyszła”.",
    "Nach „żeby“, „aby“ oder „gdyby“ hängt die Personalendung an der Konjunktion, das Verb bleibt in der bloßen Vergangenheitsform: „żebym zrobił“, „gdybyś przyszła“.",
    "Po „żeby”, „aby” i „gdyby” końcówkę osobową dołączamy do spójnika, a czasownik zostaje w formie bez niej: „żebym zrobił”, „gdybyś przyszła”.",
    "Depois de “żeby”, “aby” ou “gdyby”, a desinência de pessoa vai na conjunção e o verbo fica na forma simples do passado: “żebym zrobił”, “gdybyś przyszła”.",
  ],
